// HasRedemptions applies the HasEdge predicate on the "redemptions" edge.
func HasRedemptions() predicate.SignupCode {
	return predicate.SignupCode(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, RedemptionsTable, RedemptionsColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasRedemptionsWith applies the HasEdge predicate on the "redemptions" edge with a given conditions (other predicates).
func HasRedemptionsWith(preds ...predicate.SignupCodeRedemption) predicate.SignupCode {
	return predicate.SignupCode(func(s *sql.Selector) {
		step := newRedemptionsStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.SignupCode) predicate.SignupCode {
	return predicate.SignupCode(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.SignupCode) predicate.SignupCode {
	return predicate.SignupCode(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.SignupCode) predicate.SignupCode {
	return predicate.SignupCode(sql.NotPredicates(p))
}
